// 2026-02-14 Generated by IBM Bob
/*
    Synchronize container images from qe-ceph-manifest repository to local registry.

    This workflow follows the below steps:
        - Fetches manifest files from GitHub (ibmstorage/qe-ceph-manifest)
        - Parses YAML files for specified release and vendor
        - Routes images to appropriate local registry based on source registry
        - Syncs images using skopeo with authentication
        - Preserves full path structure (excluding source registry)

    Image Routing:
        IBM Images:
            - cp.icr.io/* -> nginx-vm-01.ceph.qe.lab:5000/ibm-prod/*
            - cp.stg.icr.io/* -> nginx-vm-01.ceph.qe.lab:5000/ibm-stage/*
            - other -> nginx-vm-01.ceph.qe.lab:5000/ibm-stage/*

        RedHat Images:
            - registry.redhat.io/* -> nginx-vm-01.ceph.qe.lab:5000/rh-prod/*
            - registry.stage.redhat.io/* -> nginx-vm-01.ceph.qe.lab:5000/rh-stage/*
            - quay.io/* -> nginx-vm-01.ceph.qe.lab:5000/rh-stage/*
            - brew.registry.redhat.io/* -> nginx-vm-01.ceph.qe.lab:5000/rh-stage/*
            - other -> nginx-vm-01.ceph.qe.lab:5000/rh-stage/*

    Note: Images in ceph/ folder are ignored.
*/

def job = pipelineJob("sync-manifest-images") {
    // Display name
    displayName("Infra - Synchronize Images from qe-ceph-manifest")

    // Description
    description("""
        Synchronizes container images from qe-ceph-manifest repository to local registry.

        Routes images based on source registry:
        - IBM prod images (cp.icr.io) -> ibm-prod/
        - IBM stage images (cp.stg.icr.io) -> ibm-stage/
        - RedHat prod images (registry.redhat.io) -> rh-prod/
        - RedHat stage images (other registries) -> rh-stage/

        Full path structure is preserved after the registry.
    """)

    definition {
        cpsScm {
            scm {
                git {
                    branch("*/main")
                    remote {
                        url("https://github.ibm.com/ceph-qe-ng/jenkins.git")
                        credentials("ceph-qe-sa-pat")
                    }
                }
            }
            scriptPath("jobs/pipelines/sync_manifest_images/Jenkinsfile")
            lightweight(true)
        }
    }

    // Parameters
    parameters {
        stringParam(
            "MANIFEST_BRANCH",
            "main",
            "Branch to fetch from qe-ceph-manifest repository"
        )
        stringParam(
            "RELEASE_VERSION",
            "",
            "Release version to sync (e.g., 9.1, 9.0, 9.2, 8.1). Leave empty to sync all available releases."
        )
        stringParam(
            "VENDOR",
            "",
            "Comma-separated list of vendors to sync (e.g., ibm,redhat or ibm or ceph,ibm,redhat). Leave empty to skip sync."
        )
        booleanParam(
            "DRY_RUN",
            false,
            "If enabled, preview images without actually syncing them"
        )
    }

    // Triggers (optional - can be enabled for scheduled sync)
    triggers {
        cron('0 2 * * *')  // Daily at 2 AM
    }
}
